def transform(grid):
    g = [row[:] for row in grid]
    cells = [(r, c) for r, row in enumerate(g) for c, v in enumerate(row) if v == 4]
    if not cells:
        return g

    rmin = min(r for r, c in cells)
    rmax = max(r for r, c in cells)
    # Reflect the 4-shape vertically and place the copy directly below it.
    for r, c in cells:
        nr = 2 * rmax + 1 - r
        if nr < len(g):
            g[nr][c] = 4

    # Remove the marker shape.
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c] == 6:
                g[r][c] = 0
    return g
